// Generated from src/registry/sources/control-ui/recipes/infinite-canvas.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const infiniteCanvasKnobs = [
  "--cui-infinite-canvas-radius",
  "--cui-infinite-canvas-background",
  "--cui-infinite-canvas-grid-dot-color",
  "--cui-infinite-canvas-border-color",
  "--cui-infinite-canvas-padding",
] as const;
export type InfiniteCanvasKnobStyle = Partial<Record<(typeof infiniteCanvasKnobs)[number], string>>;

import { CANVAS_GRID_GAP } from "@/components/control-ui/lib/canvas-grid";
import {
  boundedTransform,
  clampScale,
  fitTransform,
  type InfiniteCanvasBounds,
  type InfiniteCanvasPoint,
  type InfiniteCanvasTransform,
  revealOffset,
  sameTransform,
  toWorldPoint,
  unionBounds,
  zoomAroundPoint,
} from "@/components/control-ui/lib/infinite-canvas-camera";

export type InfiniteCanvasMoveReason = "pointer" | "pinch" | "wheel" | "keyboard" | "control" | "reveal";

export type InfiniteCanvasMoveDetails = { reason: InfiniteCanvasMoveReason };

export type InfiniteCanvasMoveOptions = { reason?: InfiniteCanvasMoveReason };

export type InfiniteCanvasZoomOptions = InfiniteCanvasMoveOptions & { origin?: InfiniteCanvasPoint };

export type InfiniteCanvasRevealOptions = InfiniteCanvasMoveOptions & { padding?: number; area?: InfiniteCanvasBounds };

export type InfiniteCanvasFitOptions = InfiniteCanvasRevealOptions & { maxScale?: number };

export type InfiniteCanvasTransformUpdate = InfiniteCanvasTransform | ((current: InfiniteCanvasTransform) => InfiniteCanvasTransform);

export type InfiniteCanvasClientPoint = { clientX: number; clientY: number };

export type InfiniteCanvasCamera = {
  getTransform: () => InfiniteCanvasTransform;
  setTransform: (update: InfiniteCanvasTransformUpdate, options?: InfiniteCanvasMoveOptions) => void;
  zoomBy: (factor: number, options?: InfiniteCanvasZoomOptions) => void;
  zoomTo: (scale: number, options?: InfiniteCanvasZoomOptions) => void;
  reset: (options?: InfiniteCanvasMoveOptions) => void;
  fit: (options?: InfiniteCanvasFitOptions) => void;
  fitBounds: (bounds: InfiniteCanvasBounds, options?: InfiniteCanvasFitOptions) => void;
  revealBounds: (bounds: InfiniteCanvasBounds, options?: InfiniteCanvasRevealOptions) => void;
  toWorldPoint: (point: InfiniteCanvasClientPoint) => InfiniteCanvasPoint;
  subscribe: (listener: () => void) => () => void;
};

export type InfiniteCanvasCameraOptions = {
  minScale: number;
  maxScale: number;
  defaultTransform: InfiniteCanvasTransform;
  controlled: boolean;
  onTransformChange?: (transform: InfiniteCanvasTransform, details: InfiniteCanvasMoveDetails) => void;
};

export type InfiniteCanvasCameraStore = InfiniteCanvasCamera & {
  camera: InfiniteCanvasCamera;
  configure: (options: InfiniteCanvasCameraOptions) => void;
  attachRoot: (element: HTMLElement | null) => void;
  attachContent: (element: HTMLElement | null) => void;
  contentElement: () => HTMLElement | null;
  getCommittedTransform: () => InfiniteCanvasTransform;
  limitScale: (scale: number) => number;
  move: (next: InfiniteCanvasTransform, reason: InfiniteCanvasMoveReason, eased?: boolean) => void;
  moveNow: (next: InfiniteCanvasTransform, reason: InfiniteCanvasMoveReason) => void;
  adopt: (next: InfiniteCanvasTransform) => void;
  revealElement: (element: Element) => void;
  toLocalPoint: (point: InfiniteCanvasClientPoint) => InfiniteCanvasPoint;
  dispose: () => void;
};

const EASED_BY_REASON: Record<InfiniteCanvasMoveReason, boolean> = {
  pointer: false,
  pinch: false,
  wheel: false,
  keyboard: true,
  control: true,
  reveal: false,
};
const CAMERA_IDLE_MS = 240;
const DEFAULT_FIT_PADDING_PX = 48;
const DEFAULT_FIT_MAX_SCALE = 1;
const DEFAULT_REVEAL_PADDING_PX = 24;
const MIN_GRID_SPACING_PX = CANVAS_GRID_GAP / 2;

export function infiniteCanvasTransformCss({ x, y, scale }: InfiniteCanvasTransform) {
  return `translate(${x}px, ${y}px) scale(${scale})`;
}

export function infiniteCanvasGridStyle({ x, y, scale }: InfiniteCanvasTransform) {
  let spacing = CANVAS_GRID_GAP * scale;
  while (spacing < MIN_GRID_SPACING_PX) spacing *= 2;
  return { backgroundPosition: `${x}px ${y}px`, backgroundSize: `${spacing}px ${spacing}px` };
}

export function createInfiniteCanvasCamera(
  initial: InfiniteCanvasTransform,
  initialOptions: InfiniteCanvasCameraOptions,
): InfiniteCanvasCameraStore {
  let options = initialOptions;
  let latest = initial;
  let committed = initial;
  let pending: { reason: InfiniteCanvasMoveReason; eased: boolean } | null = null;
  let lastEmitted: { transform: InfiniteCanvasTransform; eased: boolean } | null = null;
  let frame = 0;
  let idleTimer: ReturnType<typeof setTimeout> | undefined;
  let root: HTMLElement | null = null;
  let content: HTMLElement | null = null;
  const listeners = new Set<() => void>();

  function writeTransform() {
    if (content) {
      content.style.transform = infiniteCanvasTransformCss(committed);
      content.dataset.scale = String(committed.scale);
    }
    if (root) Object.assign(root.style, infiniteCanvasGridStyle(committed));
  }

  function markMotion(eased: boolean) {
    const element = root;
    if (!element) return;
    element.toggleAttribute("data-moving", true);
    if (eased) element.setAttribute("data-easing", "true");
    else element.removeAttribute("data-easing");
    clearTimeout(idleTimer);
    idleTimer = setTimeout(() => element.removeAttribute("data-moving"), CAMERA_IDLE_MS);
  }

  function commit(next: InfiniteCanvasTransform, eased: boolean) {
    committed = next;
    markMotion(eased);
    writeTransform();
    for (const listener of listeners) listener();
  }

  function flush() {
    frame = 0;
    if (!pending) return;
    const { reason, eased } = pending;
    pending = null;
    lastEmitted = { transform: latest, eased };
    if (!options.controlled) commit(latest, eased);
    options.onTransformChange?.(latest, { reason });
  }

  function flushNow() {
    if (!frame) return;
    cancelAnimationFrame(frame);
    flush();
  }

  function move(next: InfiniteCanvasTransform, reason: InfiniteCanvasMoveReason, eased = EASED_BY_REASON[reason]) {
    const bounded = boundedTransform(next, options.minScale, options.maxScale);
    if (!bounded || sameTransform(bounded, latest)) return;
    latest = bounded;
    pending = { reason, eased };
    frame ||= requestAnimationFrame(flush);
  }

  function viewportArea(): InfiniteCanvasBounds {
    return { x: 0, y: 0, width: root?.clientWidth ?? 0, height: root?.clientHeight ?? 0 };
  }

  function toLocalPoint(point: InfiniteCanvasClientPoint): InfiniteCanvasPoint {
    const bounds = root?.getBoundingClientRect();
    return { x: point.clientX - (bounds?.left ?? 0), y: point.clientY - (bounds?.top ?? 0) };
  }

  function contentBounds() {
    if (!content) return null;
    const origin = content.getBoundingClientRect();
    const renderedScale = new DOMMatrixReadOnly(getComputedStyle(content).transform).a || committed.scale;
    const rects: InfiniteCanvasBounds[] = [];
    for (const child of content.children) {
      for (const element of [child, ...child.children]) {
        const bounds = element.getBoundingClientRect();
        if (bounds.width === 0 && bounds.height === 0) continue;
        rects.push({
          x: (bounds.left - origin.left) / renderedScale,
          y: (bounds.top - origin.top) / renderedScale,
          width: bounds.width / renderedScale,
          height: bounds.height / renderedScale,
        });
      }
    }
    return unionBounds(rects);
  }

  function revealScreenBounds(screenBounds: InfiniteCanvasBounds, revealOptions: InfiniteCanvasRevealOptions) {
    const offset = revealOffset(screenBounds, revealOptions.area ?? viewportArea(), revealOptions.padding ?? DEFAULT_REVEAL_PADDING_PX);
    if (offset.x === 0 && offset.y === 0) return;
    move({ ...latest, x: latest.x + offset.x, y: latest.y + offset.y }, revealOptions.reason ?? "control");
  }

  function zoomTo(scale: number, zoomOptions: InfiniteCanvasZoomOptions = {}) {
    const area = viewportArea();
    const origin = zoomOptions.origin ?? { x: area.width / 2, y: area.height / 2 };
    move(zoomAroundPoint(latest, clampScale(scale, options.minScale, options.maxScale), origin), zoomOptions.reason ?? "control");
  }

  function fitBounds(bounds: InfiniteCanvasBounds, fitOptions: InfiniteCanvasFitOptions = {}) {
    const limits = {
      padding: fitOptions.padding ?? DEFAULT_FIT_PADDING_PX,
      minScale: options.minScale,
      maxScale: Math.min(fitOptions.maxScale ?? DEFAULT_FIT_MAX_SCALE, options.maxScale),
    };
    move(fitTransform(bounds, fitOptions.area ?? viewportArea(), limits), fitOptions.reason ?? "control");
  }

  const camera: InfiniteCanvasCamera = {
    getTransform: () => latest,
    setTransform(update, moveOptions = {}) {
      move(typeof update === "function" ? update(latest) : update, moveOptions.reason ?? "control");
    },
    zoomTo,
    zoomBy(factor, zoomOptions = {}) {
      zoomTo(latest.scale * factor, zoomOptions);
    },
    reset(moveOptions = {}) {
      move(options.defaultTransform, moveOptions.reason ?? "control");
    },
    fitBounds,
    fit(fitOptions = {}) {
      const bounds = contentBounds();
      if (bounds) fitBounds(bounds, fitOptions);
      else move(options.defaultTransform, fitOptions.reason ?? "control");
    },
    revealBounds(bounds, revealOptions = {}) {
      const screenBounds = {
        x: latest.x + bounds.x * latest.scale,
        y: latest.y + bounds.y * latest.scale,
        width: bounds.width * latest.scale,
        height: bounds.height * latest.scale,
      };
      revealScreenBounds(screenBounds, revealOptions);
    },
    toWorldPoint: (point) => toWorldPoint(latest, toLocalPoint(point)),
    subscribe(listener) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };

  return {
    ...camera,
    camera,
    configure(next) {
      options = next;
    },
    attachRoot(element) {
      root = element;
      writeTransform();
    },
    attachContent(element) {
      content = element;
      writeTransform();
    },
    contentElement: () => content,
    getCommittedTransform: () => committed,
    limitScale: (scale) => clampScale(scale, options.minScale, options.maxScale),
    move,
    moveNow(next, reason) {
      move(next, reason, false);
      flushNow();
    },
    adopt(next) {
      const bounded = boundedTransform(next, options.minScale, options.maxScale);
      if (!bounded) return;
      const echo = lastEmitted && sameTransform(bounded, lastEmitted.transform) ? lastEmitted : null;
      if (!echo) {
        cancelAnimationFrame(frame);
        frame = 0;
        pending = null;
      }
      if (!pending) latest = bounded;
      if (!sameTransform(bounded, committed)) commit(bounded, echo?.eased ?? false);
    },
    revealElement(element) {
      const bounds = element.getBoundingClientRect();
      const origin = toLocalPoint({ clientX: bounds.left, clientY: bounds.top });
      revealScreenBounds({ ...origin, width: bounds.width, height: bounds.height }, { reason: "reveal" });
      flushNow();
    },
    toLocalPoint,
    dispose() {
      flushNow();
      clearTimeout(idleTimer);
    },
  };
}

export type InfiniteCanvasTransform = { x: number; y: number; scale: number };

export type InfiniteCanvasPoint = { x: number; y: number };

export type InfiniteCanvasBounds = { x: number; y: number; width: number; height: number };

export type CanvasWheelInput = Pick<WheelEvent, "deltaMode" | "deltaX" | "deltaY" | "shiftKey">;

const MAX_CAMERA_OFFSET_PX = 10_000_000;
const WHEEL_LINE_HEIGHT_PX = 16;
const DOM_DELTA_LINE = 1;
const DOM_DELTA_PAGE = 2;

export function clampScale(scale: number, minScale: number, maxScale: number) {
  return Math.min(Math.max(scale, minScale), maxScale);
}

export function sameTransform(left: InfiniteCanvasTransform, right: InfiniteCanvasTransform) {
  return left.x === right.x && left.y === right.y && left.scale === right.scale;
}

export function boundedTransform(next: InfiniteCanvasTransform, minScale: number, maxScale: number): InfiniteCanvasTransform | null {
  if (!(Number.isFinite(next.x) && Number.isFinite(next.y) && Number.isFinite(next.scale)) || next.scale <= 0) return null;
  return {
    x: Math.min(Math.max(next.x, -MAX_CAMERA_OFFSET_PX), MAX_CAMERA_OFFSET_PX),
    y: Math.min(Math.max(next.y, -MAX_CAMERA_OFFSET_PX), MAX_CAMERA_OFFSET_PX),
    scale: clampScale(next.scale, minScale, maxScale),
  };
}

export function toWorldPoint(transform: InfiniteCanvasTransform, point: InfiniteCanvasPoint): InfiniteCanvasPoint {
  return { x: (point.x - transform.x) / transform.scale, y: (point.y - transform.y) / transform.scale };
}

export function zoomAroundPoint(
  transform: InfiniteCanvasTransform,
  nextScale: number,
  point: InfiniteCanvasPoint,
): InfiniteCanvasTransform {
  const world = toWorldPoint(transform, point);
  return { x: point.x - world.x * nextScale, y: point.y - world.y * nextScale, scale: nextScale };
}

export function pinchTransform(
  start: InfiniteCanvasTransform,
  startMidpoint: InfiniteCanvasPoint,
  midpoint: InfiniteCanvasPoint,
  nextScale: number,
): InfiniteCanvasTransform {
  const zoomed = zoomAroundPoint(start, nextScale, startMidpoint);
  return { x: zoomed.x + midpoint.x - startMidpoint.x, y: zoomed.y + midpoint.y - startMidpoint.y, scale: nextScale };
}

export function wheelDeltaMultiplier(deltaMode: number, pageHeight: number) {
  if (deltaMode === DOM_DELTA_LINE) return WHEEL_LINE_HEIGHT_PX;
  if (deltaMode === DOM_DELTA_PAGE) return pageHeight;
  return 1;
}

export function wheelDeltaPixels(event: CanvasWheelInput, pageHeight: number): InfiniteCanvasPoint {
  const multiplier = wheelDeltaMultiplier(event.deltaMode, pageHeight);
  const verticalAsHorizontal = event.shiftKey && event.deltaX === 0;
  return {
    x: (verticalAsHorizontal ? event.deltaY : event.deltaX) * multiplier,
    y: (verticalAsHorizontal ? 0 : event.deltaY) * multiplier,
  };
}

export function unionBounds(bounds: readonly InfiniteCanvasBounds[]): InfiniteCanvasBounds | null {
  if (bounds.length === 0) return null;
  let left = Number.POSITIVE_INFINITY;
  let top = Number.POSITIVE_INFINITY;
  let right = Number.NEGATIVE_INFINITY;
  let bottom = Number.NEGATIVE_INFINITY;
  for (const entry of bounds) {
    left = Math.min(left, entry.x);
    top = Math.min(top, entry.y);
    right = Math.max(right, entry.x + entry.width);
    bottom = Math.max(bottom, entry.y + entry.height);
  }
  return { x: left, y: top, width: right - left, height: bottom - top };
}

export function fitTransform(
  bounds: InfiniteCanvasBounds,
  area: InfiniteCanvasBounds,
  limits: { padding: number; minScale: number; maxScale: number },
): InfiniteCanvasTransform {
  const availableWidth = Math.max(1, area.width - limits.padding * 2);
  const availableHeight = Math.max(1, area.height - limits.padding * 2);
  const scale = clampScale(
    Math.min(availableWidth / Math.max(bounds.width, 1), availableHeight / Math.max(bounds.height, 1)),
    limits.minScale,
    limits.maxScale,
  );
  return {
    x: area.x + area.width / 2 - (bounds.x + bounds.width / 2) * scale,
    y: area.y + area.height / 2 - (bounds.y + bounds.height / 2) * scale,
    scale,
  };
}

function revealAxisOffset(start: number, size: number, areaStart: number, areaSize: number, padding: number) {
  const visibleStart = areaStart + padding;
  const visibleEnd = areaStart + areaSize - padding;
  if (size > visibleEnd - visibleStart || start < visibleStart) return visibleStart - start;
  if (start + size > visibleEnd) return visibleEnd - (start + size);
  return 0;
}

export function revealOffset(screenBounds: InfiniteCanvasBounds, area: InfiniteCanvasBounds, padding: number): InfiniteCanvasPoint {
  return {
    x: revealAxisOffset(screenBounds.x, screenBounds.width, area.x, area.width, padding),
    y: revealAxisOffset(screenBounds.y, screenBounds.height, area.y, area.height, padding),
  };
}

import {
  type InfiniteCanvasPoint,
  type InfiniteCanvasTransform,
  pinchTransform,
  wheelDeltaMultiplier,
  wheelDeltaPixels,
  zoomAroundPoint,
} from "@/components/control-ui/lib/infinite-canvas-camera";
import type { InfiniteCanvasCameraStore } from "@/components/control-ui/lib/infinite-canvas-camera-store";

export type InfiniteCanvasPanOnDrag = "background" | "anywhere" | "never";

export type InfiniteCanvasNavigationOptions = {
  panOnDrag: InfiniteCanvasPanOnDrag;
  onWheel?: (event: WheelEvent) => void;
};

export type InfiniteCanvasNavigation = {
  beginBackgroundPan: (event: PointerEvent) => void;
  syncPanReady: () => void;
  detach: () => void;
};

type PanGesture = {
  kind: "pan";
  pointerId: number;
  button: number;
  explicit: boolean;
  moved: boolean;
  startPointer: InfiniteCanvasPoint;
  startTransform: InfiniteCanvasTransform;
};

type PinchGesture = {
  kind: "pinch";
  pointerIds: readonly number[];
  startDistance: number;
  startMidpoint: InfiniteCanvasPoint;
  startTransform: InfiniteCanvasTransform;
};

type NavigationGesture = PanGesture | PinchGesture;

export const INFINITE_CANVAS_KEY_SHORTCUTS = "ArrowLeft ArrowRight ArrowUp ArrowDown + - 0 1";

export const ARROW_KEY_DIRECTIONS: Partial<Record<string, InfiniteCanvasPoint>> = {
  ArrowLeft: { x: -1, y: 0 },
  ArrowRight: { x: 1, y: 0 },
  ArrowUp: { x: 0, y: -1 },
  ArrowDown: { x: 0, y: 1 },
};

const KEYBOARD_ZOOM_FACTORS: Partial<Record<string, number>> = { "+": 1.15, "=": 1.15, "-": 1 / 1.15 };
const KEYBOARD_STEP_PX = 32;
const WHEEL_ZOOM_SPEED = 0.004;
const MAX_WHEEL_ZOOM_DELTA = 50;
const NOTCHED_WHEEL_DELTA = 40;
const CLICK_SLOP_PX = 3;
const MIDDLE_BUTTON = 1;
const SCROLLABLE_OVERFLOW = /auto|scroll|overlay/;
const SPACE_CONSUMING_ROLES = [
  "button",
  "checkbox",
  "combobox",
  "menuitem",
  "option",
  "radio",
  "slider",
  "spinbutton",
  "switch",
  "tab",
  "textbox",
];
const SPACE_CONSUMING_TARGET = [
  "input",
  "textarea",
  "select",
  "button",
  "a[href]",
  "[contenteditable]:not([contenteditable='false'])",
  ...SPACE_CONSUMING_ROLES.map((role) => `[role='${role}']`),
].join(", ");

export function keyboardStep(shiftKey: boolean) {
  return shiftKey ? KEYBOARD_STEP_PX * 3 : KEYBOARD_STEP_PX;
}

export function runInfiniteCanvasKeyCommand(camera: InfiniteCanvasCameraStore, key: string, shiftKey: boolean) {
  const direction = ARROW_KEY_DIRECTIONS[key];
  if (direction) {
    const current = camera.getTransform();
    const step = keyboardStep(shiftKey);
    camera.move({ ...current, x: current.x - direction.x * step, y: current.y - direction.y * step }, "keyboard");
    return true;
  }
  const zoomFactor = KEYBOARD_ZOOM_FACTORS[key];
  if (zoomFactor) camera.zoomBy(zoomFactor, { reason: "keyboard" });
  else if (key === "0") camera.reset({ reason: "keyboard" });
  else if (key === "1") camera.fit({ reason: "keyboard" });
  else return false;
  return true;
}

function canScrollFurther(element: Element, delta: InfiniteCanvasPoint) {
  if (element.scrollHeight <= element.clientHeight && element.scrollWidth <= element.clientWidth) return false;
  const { overflowX, overflowY } = getComputedStyle(element);
  const verticalRoom = delta.y < 0 ? element.scrollTop > 0 : Math.ceil(element.scrollTop + element.clientHeight) < element.scrollHeight;
  const horizontalRoom = delta.x < 0 ? element.scrollLeft > 0 : Math.ceil(element.scrollLeft + element.clientWidth) < element.scrollWidth;
  return (
    (delta.y !== 0 && SCROLLABLE_OVERFLOW.test(overflowY) && verticalRoom) ||
    (delta.x !== 0 && SCROLLABLE_OVERFLOW.test(overflowX) && horizontalRoom)
  );
}

function nestedScrollerConsumes(target: EventTarget | null, root: HTMLElement, delta: InfiniteCanvasPoint) {
  for (let element = target instanceof Element ? target : null; element && element !== root; element = element.parentElement) {
    if (canScrollFurther(element, delta)) return true;
  }
  return false;
}

function gesturePointerIds(active: NavigationGesture) {
  return active.kind === "pan" ? [active.pointerId] : active.pointerIds;
}

function clickAfterGesture(ended: NavigationGesture) {
  if (ended.kind === "pinch") return "click";
  if (!(ended.explicit || ended.moved)) return null;
  return ended.button === MIDDLE_BUTTON ? "auxclick" : "click";
}

function gestureScale(event: Event) {
  return "scale" in event && typeof event.scale === "number" ? event.scale : null;
}

function gestureClientPoint(event: Event) {
  if (!("clientX" in event && "clientY" in event)) return null;
  const { clientX, clientY } = event;
  return typeof clientX === "number" && typeof clientY === "number" ? { clientX, clientY } : null;
}

export function attachInfiniteCanvasNavigation(
  root: HTMLElement,
  camera: InfiniteCanvasCameraStore,
  readOptions: () => InfiniteCanvasNavigationOptions,
): InfiniteCanvasNavigation {
  const listeners = new AbortController();
  const { signal } = listeners;
  const touches = new Map<number, InfiniteCanvasPoint>();
  let gesture: NavigationGesture | null = null;
  let spaceHeld = false;
  let safariPinchStartScale: number | null = null;
  let suppressedClick: string | null = null;
  let suppressedClickTimer: ReturnType<typeof setTimeout> | undefined;
  let pointerFocus = false;
  let pointerFocusTimer: ReturnType<typeof setTimeout> | undefined;

  function syncPanReady() {
    root.toggleAttribute("data-pan-ready", spaceHeld || readOptions().panOnDrag === "anywhere");
  }

  function suppressNextClick(type: "click" | "auxclick") {
    suppressedClick = type;
    clearTimeout(suppressedClickTimer);
    suppressedClickTimer = setTimeout(() => {
      suppressedClick = null;
    });
  }

  function startPan(event: PointerEvent, explicit: boolean) {
    root.setPointerCapture(event.pointerId);
    root.toggleAttribute("data-panning", true);
    gesture = {
      kind: "pan",
      pointerId: event.pointerId,
      button: event.button,
      explicit,
      moved: false,
      startPointer: { x: event.clientX, y: event.clientY },
      startTransform: camera.getTransform(),
    };
  }

  function startPinch() {
    const [first, second] = [...touches.entries()];
    if (!(first && second)) return;
    for (const [pointerId] of [first, second]) {
      if (!root.hasPointerCapture(pointerId)) root.setPointerCapture(pointerId);
    }
    root.toggleAttribute("data-panning", true);
    gesture = {
      kind: "pinch",
      pointerIds: [first[0], second[0]],
      startDistance: Math.max(1, Math.hypot(first[1].x - second[1].x, first[1].y - second[1].y)),
      startMidpoint: camera.toLocalPoint({ clientX: (first[1].x + second[1].x) / 2, clientY: (first[1].y + second[1].y) / 2 }),
      startTransform: camera.getTransform(),
    };
  }

  function involvesPointer(pointerId: number) {
    return gesture !== null && gesturePointerIds(gesture).includes(pointerId);
  }

  function finishGesture() {
    const ended = gesture;
    if (!ended) return;
    gesture = null;
    root.removeAttribute("data-panning");
    for (const pointerId of gesturePointerIds(ended)) {
      if (root.hasPointerCapture(pointerId)) root.releasePointerCapture(pointerId);
    }
    const click = clickAfterGesture(ended);
    if (click) suppressNextClick(click);
  }

  function claim(event: PointerEvent) {
    event.preventDefault();
    event.stopPropagation();
  }

  function isNavigableTarget(target: EventTarget | null) {
    return target === root || (target instanceof Node && camera.contentElement()?.contains(target) === true);
  }

  function markPointerFocus() {
    pointerFocus = true;
    clearTimeout(pointerFocusTimer);
    pointerFocusTimer = setTimeout(() => {
      pointerFocus = false;
    });
  }

  function claimsTouchPinch(event: PointerEvent) {
    if (event.pointerType !== "touch") return false;
    if (event.isPrimary) touches.clear();
    touches.set(event.pointerId, { x: event.clientX, y: event.clientY });
    if (touches.size < 2) return false;
    claim(event);
    if (touches.size === 2) startPinch();
    return true;
  }

  function isExplicitPan(event: PointerEvent) {
    if (!isNavigableTarget(event.target)) return false;
    if (event.button === MIDDLE_BUTTON) return true;
    return event.button === 0 && (spaceHeld || readOptions().panOnDrag === "anywhere");
  }

  function claimNavigationPointer(event: PointerEvent) {
    markPointerFocus();
    if (claimsTouchPinch(event) || gesture || !event.isPrimary || !isExplicitPan(event)) return;
    claim(event);
    startPan(event, true);
  }

  function followPointer(event: PointerEvent) {
    if (touches.has(event.pointerId)) touches.set(event.pointerId, { x: event.clientX, y: event.clientY });
    if (!(gesture && involvesPointer(event.pointerId))) return;
    if (gesture.kind === "pan") {
      const deltaX = event.clientX - gesture.startPointer.x;
      const deltaY = event.clientY - gesture.startPointer.y;
      if (Math.hypot(deltaX, deltaY) > CLICK_SLOP_PX) gesture.moved = true;
      const { startTransform } = gesture;
      camera.move({ ...startTransform, x: startTransform.x + deltaX, y: startTransform.y + deltaY }, "pointer");
      return;
    }
    const [first, second] = gesture.pointerIds.map((pointerId) => touches.get(pointerId));
    if (!(first && second)) return;
    const midpoint = camera.toLocalPoint({ clientX: (first.x + second.x) / 2, clientY: (first.y + second.y) / 2 });
    const ratio = Math.hypot(first.x - second.x, first.y - second.y) / gesture.startDistance;
    const nextScale = camera.limitScale(gesture.startTransform.scale * ratio);
    camera.move(pinchTransform(gesture.startTransform, gesture.startMidpoint, midpoint, nextScale), "pinch");
  }

  function releasePointer(event: PointerEvent) {
    touches.delete(event.pointerId);
    if (involvesPointer(event.pointerId)) finishGesture();
  }

  function zoomWithWheel(event: WheelEvent) {
    event.preventDefault();
    if (safariPinchStartScale !== null) return;
    const current = camera.getTransform();
    const zoomDelta = event.deltaY * wheelDeltaMultiplier(event.deltaMode, root.clientHeight);
    const boundedDelta = Math.min(Math.max(zoomDelta, -MAX_WHEEL_ZOOM_DELTA), MAX_WHEEL_ZOOM_DELTA);
    const nextScale = camera.limitScale(current.scale * Math.exp(-boundedDelta * WHEEL_ZOOM_SPEED));
    camera.move(zoomAroundPoint(current, nextScale, camera.toLocalPoint(event)), "wheel", Math.abs(zoomDelta) >= NOTCHED_WHEEL_DELTA);
  }

  function handleWheel(event: WheelEvent) {
    readOptions().onWheel?.(event);
    if (event.defaultPrevented) return;
    if (event.ctrlKey || event.metaKey) {
      zoomWithWheel(event);
      return;
    }
    const delta = wheelDeltaPixels(event, root.clientHeight);
    if (nestedScrollerConsumes(event.target, root, delta)) return;
    event.preventDefault();
    const current = camera.getTransform();
    camera.move({ ...current, x: current.x - delta.x, y: current.y - delta.y }, "wheel");
  }

  function startSafariPinch(event: Event) {
    event.preventDefault();
    safariPinchStartScale = camera.getTransform().scale;
  }

  function followSafariPinch(event: Event) {
    event.preventDefault();
    const scale = gestureScale(event);
    if (safariPinchStartScale === null || scale === null || gesture?.kind === "pinch") return;
    const clientPoint = gestureClientPoint(event);
    const origin = clientPoint ? camera.toLocalPoint(clientPoint) : { x: root.clientWidth / 2, y: root.clientHeight / 2 };
    camera.move(zoomAroundPoint(camera.getTransform(), camera.limitScale(safariPinchStartScale * scale), origin), "pinch");
  }

  function endSafariPinch(event: Event) {
    event.preventDefault();
    safariPinchStartScale = null;
  }

  function armSpacePan(event: KeyboardEvent) {
    if (event.code !== "Space") return;
    if (spaceHeld) {
      event.preventDefault();
      return;
    }
    if (event.defaultPrevented || event.repeat || event.isComposing || event.ctrlKey || event.metaKey || event.altKey) return;
    const { target } = event;
    if (target instanceof HTMLElement && (target.isContentEditable || target.matches(SPACE_CONSUMING_TARGET))) return;
    if (!(root.contains(document.activeElement) || root.matches(":hover"))) return;
    event.preventDefault();
    spaceHeld = true;
    syncPanReady();
  }

  function disarmSpacePan(event: KeyboardEvent) {
    if (event.code !== "Space" || !spaceHeld) return;
    spaceHeld = false;
    syncPanReady();
  }

  function releaseHeldInput() {
    spaceHeld = false;
    safariPinchStartScale = null;
    touches.clear();
    finishGesture();
    syncPanReady();
  }

  function swallowClickAfterPan(event: MouseEvent) {
    if (event.type !== suppressedClick) return;
    suppressedClick = null;
    event.preventDefault();
    event.stopPropagation();
  }

  function revealKeyboardFocus(event: FocusEvent) {
    if (pointerFocus || !(event.target instanceof Element)) return;
    if (camera.contentElement()?.contains(event.target)) camera.revealElement(event.target);
  }

  function absorbNativeScroll() {
    const { scrollLeft, scrollTop } = root;
    if (scrollLeft === 0 && scrollTop === 0) return;
    root.scrollTo(0, 0);
    const current = camera.getTransform();
    camera.moveNow({ ...current, x: current.x - scrollLeft, y: current.y - scrollTop }, "reveal");
  }

  root.addEventListener("pointerdown", claimNavigationPointer, { capture: true, signal });
  root.addEventListener("pointermove", followPointer, { capture: true, signal });
  root.addEventListener("pointerup", releasePointer, { capture: true, signal });
  root.addEventListener("pointercancel", releasePointer, { capture: true, signal });
  root.addEventListener(
    "lostpointercapture",
    (event) => {
      if (event.target === root && involvesPointer(event.pointerId)) finishGesture();
    },
    { signal },
  );
  root.addEventListener("click", swallowClickAfterPan, { capture: true, signal });
  root.addEventListener("auxclick", swallowClickAfterPan, { capture: true, signal });
  root.addEventListener(
    "mousedown",
    (event) => {
      if (event.button === MIDDLE_BUTTON && isNavigableTarget(event.target)) event.preventDefault();
    },
    { signal },
  );
  root.addEventListener("wheel", handleWheel, { passive: false, signal });
  root.addEventListener("gesturestart", startSafariPinch, { signal });
  root.addEventListener("gesturechange", followSafariPinch, { signal });
  root.addEventListener("gestureend", endSafariPinch, { signal });
  root.addEventListener("focusin", revealKeyboardFocus, { signal });
  root.addEventListener("scroll", absorbNativeScroll, { signal });
  window.addEventListener("keydown", armSpacePan, { signal });
  window.addEventListener("keyup", disarmSpacePan, { signal });
  window.addEventListener("blur", releaseHeldInput, { signal });
  document.addEventListener(
    "visibilitychange",
    () => {
      if (document.visibilityState === "hidden") releaseHeldInput();
    },
    { signal },
  );
  syncPanReady();

  return {
    beginBackgroundPan(event) {
      if (gesture || event.defaultPrevented || event.target !== root || !event.isPrimary || event.button !== 0) return;
      if (readOptions().panOnDrag === "background") startPan(event, false);
    },
    syncPanReady,
    detach() {
      listeners.abort();
      clearTimeout(suppressedClickTimer);
      clearTimeout(pointerFocusTimer);
      releaseHeldInput();
      root.removeAttribute("data-pan-ready");
    },
  };
}

